        angle = (360.0f / particleP->maxCnt) * i;
        dist = work->unk018 + (s32)frandmod((s32)(work->unk018 / 4.0f));
        data->pos.x = dist * sin(M_PI * angle / 180.0);
        data->pos.z = dist * cos(M_PI * angle / 180.0);
