        data->vel.x = 5.0 * sin(M_PI * angle / 180.0);
        data->vel.y = 9.0f + (s32)frandmod(2);
        data->vel.z = 5.0 * cos(M_PI * angle / 180.0);
        data->accel.x = 30.0f;
        data->accel.y = 15.0f;
        data->accel.z = 17.0f;
        data->scale = 80.0f + (s32)frandmod(20);
