/* 154 insns */
void fn_1_E2A0(M518_SMOKE *work, HU3DMODEL *modelP, HU3DPARTICLE *particleP, Mtx mtx)
{
    HU3DPARTICLEDATA *data;
    s32 i;
    s32 alpha;

    for (i = 0, data = particleP->data; i < particleP->maxCnt; i++, data++) {
        if (0.0f != data->accel.x) {
            data->pos.x += data->vel.x;
            data->pos.y += data->vel.y;
            data->pos.z += data->vel.z;
            data->vel.x *= 0.95f;
            data->vel.z *= 0.95f;
            if (data->vel.y > 0.1f) {
                data->vel.y -= 0.2f;
            }
            if (data->vel.y < 0.0f) {
                data->vel.y = 0.0f;
            }
            data->scale += data->accel.y;
            if (data->accel.y > 2.0f) {
                data->accel.y -= 1.5f;
            }
            alpha = data->color.a;
            alpha = alpha - data->accel.z;
            if (data->accel.z > 3.0f) {
                data->accel.z -= 1.0f;
            }
            if (alpha < 0) {
                alpha = 0;
                data->accel.x = 0.0f;
            }
            data->color.a = alpha;
            if (0.0f == data->accel.x) {
                data->scale = 0.0f;
            }
        }
    }
    if (particleP->emitCnt++ > 60) {
        HU3DMODEL *modelP;
        HU3DPARTICLE *killP;

        work->unk000 = 0;
        Hu3DModelAttrSet(work->unk004, HU3D_ATTR_DISPOFF);
        modelP = &Hu3DData[work->unk004];
        killP = modelP->hookData;
        killP->dataCnt = 0;
    }
}

